{'code': "from qgis.core import QgsApplication
alg = QgsApplication.processingRegistry().algorithmById('native:raisewarning')
if alg is None:
    result = {'exists': False}
else:
    result = {
        'exists': True,
        'id': alg.id(),
        'name': alg.name(),
        'displayName': alg.displayName(),
        'group': alg.group(),
        'provider': alg.provider().name() if alg.provider() else None,
        'parameters': [
            {
                'name': p.name(),
                'description': p.description(),
                'type': p.type(),
                'defaultValue': p.defaultValue(),
                'optional': bool(p.flags() & p.FlagOptional),
            }
            for p in alg.parameterDefinitions()
        ],
        'outputs': [
            {'name': o.name(), 'description': o.description(), 'type': o.type()}
            for o in alg.outputDefinitions()
        ],
        'shortHelp': alg.shortHelpString(),
    }"}
